curl -s -X POST https://slack.com/api/users.list -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for member in data['members']:
        if 'maya' in member.get('real_name','').lower() or 'maya' in member.get('profile',{}).get('display_name','').lower():
            print(json.dumps(member, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/conversations.history -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&channel=D_MAYA&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        print(f\"ts={msg['ts']}, user={msg['user']}, text={msg.get('text','')}\")
else:
    print(json.dumps(data, indent=2))
"
